# ===========================================================================
# THE WORLD, as built in the game (game/level/level_art.gd and game/world/).
# Every piece is drawn at 128 px per tile; the game shows it at half size on
# its 64-px tiles.
# ===========================================================================
CARDS += [
    card("W0", "world-first", "target", "world_target_bedroom", "Target render: Cowl's bedroom, repainted",
         "Locks the world's look on a real screen of the game. SOL repaints the bedroom screenshot (D) in the style of your mansion paintings, keeping every floor, wall and opening exactly where the collision has it. Every world card attaches it once you approve it.",
         SCREEN, REF, ["D", "B", "C", "A"],
         "TASK: repaint the attached game screenshot D, Cowl's bedroom, as a finished screen in the style of images B and C. Keep the composition exactly: every edge between the black solid shapes and the open purple rooms stays exactly where it is in D, to the pixel, because those edges are the game's collision.",
         [
             "The black shapes are solid: the house's masonry floors and walls, buried in black earth. Paint them as packed near-black earth threaded with roots, with the mansion's dark masonry showing along every edge that faces a room: thick stone floors with a carved lip along their tops, vault stones and hanging moss along the undersides of ceilings, as in B and C.",
             "The open purple areas are the rooms: a gothic bedroom with panelled walls, two tall lancet windows (where D has them) glowing faintly with lavender haze, the canopy bed, clock and candelabra on the left (repaint them sharper, as in B), and the heap of slid furniture on the right standing where the two black blocks are (their tops stay flat and walkable).",
             "Below, through the floor: the green-tinted conservatory and the hallway's arches, as in D.",
             "Cowl stays where he is in D, at the same size (about 128 px tall), mid-jump, drawn exactly as image A.",
             "Ignore the five round dots at the top left of D (the game's health display): paint the scene behind them.",
             "The playfield's back walls stay in the mid violets so Cowl's charcoal body reads in front; only the earth and the foreground go near-black. Candle flames are flat pale rose shapes with their light painted softly around them.",
         ], outline=WLINE, pilot=True),
    card("W1", "world-first", "target", "world_target_grand_hall", "Target render: the grand entrance hall, repainted",
         "The showpiece room, shown zoomed out: galleries, the broken grand stair, the mound of its fallen flight and the arcades behind. SOL repaints the screenshot (E) keeping every edge, so the stair and gallery kit has a target to match.",
         SCREEN, REF, ["E", "W0", "B", "C"],
         "TASK: repaint the attached game screenshot E, the grand entrance hall (seen zoomed out), as a finished screen in the style of images B and C and the approved target render W0. Keep the composition exactly: every edge of the black solid shapes, every stair line and every gallery stays where it is in E, because those are the game's collision.",
         [
             "The galleries are thick stone floors with a carved lip and wrought-iron railings with spear-topped newels, as in B.",
             "The stairs are stone flights with treads under the walking line and iron balustrades; the upper flights are broken off short, their broken ends jagged and hanging, as the house fell.",
             "Behind everything, the hall opens into tiers of gothic arcades and galleries fading into lavender haze, deeper and paler the further back they are, as in B and C.",
             "Cowl stays where he is in E, at the same size, drawn exactly as image A. Paint over the 'Dodge [Shift]' prompt and the dots at the top left.",
             "Candle flames are flat pale rose shapes with their light painted softly around them; the chandelier on the right hangs on its chain.",
         ], outline=WLINE, pilot=True),
    card("W2", "world-first", "world", "world_materials", "Materials sheet",
         "The world's materials painted as square swatches, so every kit piece after it matches: earth, masonry, carved trim, iron, wood, velvet, candles and the cellar's wet stone. Approve with W0.",
         EIGHT, REF, ["W0", "B", "C"],
         "TASK: a materials sheet for the buried mansion: eight square swatches, one per cell, each a close study of one material filling its cell, painted in the style and light of the approved target render (W0).",
         [
             "Packed black earth threaded with roots and small buried stones (the solid mass between the rooms).",
             "The mansion's masonry: cut stone blocks in violet, with mortar lines, chips and a little moss.",
             "Carved gothic stone trim: a moulding with a pointed-arch motif.",
             "Wrought iron: a section of railing with a spear finial and scrollwork.",
             "Dark old wood: floorboards and a carved panel.",
             "Plum velvet: a draped curtain fold and a tufted cushion.",
             "Candles: pale lilac wax with drips, and one flat pale rose flame shape.",
             "Cellar stone: rough damp blocks, a dark water line and a few roots coming through.",
         ], outline=WLINE),
]

# ---- Parallax --------------------------------------------------------------
CARDS += [
    card("W3", "layers", "layer", "world_layer_far", "Parallax 1: the far arcades",
         "The deepest layer, behind every room with an open view (the game scrolls it at a tenth of the camera's speed): tiers of tiny gothic arcades lost in lavender haze. Replaces the code-drawn far arcade.",
         WIDE, LAYER, ["W0", "W1", "B", "C"],
         "TASK: the farthest background layer of the buried mansion, one painting, seamless left to right (its left edge continues its right edge exactly). Two tiers of gothic arcades, one above the other, small and far away, with balustrades between them, their openings filled with soft lavender light low in each arch, everything melting into indigo haze, as in the depths of images B and C. Very low contrast (#46437F to #8A80BE), lightest in the middle band, darker at the top and bottom. Soft, with no fine detail: the game enlarges it. No floor line, no roots, nothing that could look walkable.",
         [], outline=WLINE),
    card("W4", "layers", "layer", "world_layer_mid", "Parallax 2: the middle galleries",
         "The middle layer (scrolled at about a quarter of the camera's speed): larger galleries, distant staircases and chandeliers in silhouette, with open gaps the far arcades show through.",
         WIDE, LAYER, ["W0", "W3", "B"],
         "TASK: the middle background layer of the mansion, one painting, seamless left to right. Larger, closer gothic galleries: arcades on two levels with iron railings, a distant staircase climbing between them, two chandeliers hanging in silhouette, slightly darker and clearer than the far arcades (attached W3), still in the mid violets (#37356B to #57528F) and softened by haze. Where the far arcades should show through (the openings of the arches and the air between the galleries), leave the canvas fully transparent.",
         [], outline=WLINE),
    card("W5", "layers", "layer", "world_layer_near", "Parallax 3: the near arcade",
         "The nearest background layer (scrolled at about half the camera's speed): a tall arcade of big pointed arches and piers just behind the playfield. Tall, so it fills the grand hall's height when the camera zooms out.",
         TALLWIDE, LAYER, ["W0", "W1", "W4", "B"],
         "TASK: the nearest background layer of the mansion, one tall painting, seamless left to right. A colossal gothic arcade just behind the rooms: tall pointed arches on clustered piers, a tier of smaller arches above them and the ribs of a vault at the top, darker and more detailed than the middle galleries (attached W4) but still softened by haze (#262450 to #4A4680), so the playfield reads in front. Leave the arch openings fully transparent so the layers behind show through.",
         [], outline=WLINE),
    card("W6", "layers", "layer", "world_layer_flooded", "Parallax: the flooded vaults (the undercroft)",
         "Behind the undercroft under the hall, flooded at its far end: rows of low arches standing in still water, receding into blue darkness, as at the bottom of both mockups.",
         WIDE, LAYER, ["W0", "B", "C"],
         "TASK: a background layer for the undercroft, one painting, seamless left to right: rows of low, heavy cellar arches and squat pillars standing in still water, receding into darkness, as at the bottom of images B and C. The water's far surface glints a muted blue (#566FA5) under the arches; everything else is deep indigo (#16204A to #2E3A6E). No near water line (the game draws it).",
         [], outline=WLINE),
]

